cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int WARPS_PER_BLOCK = 8;
constexpr int THREADS_PER_BLOCK = WARPS_PER_BLOCK * 32;

__global__ void cute_conv_transpose3d_kernel(
    const float* x_ptr,
    const float* w_ptr,
    const float* bias_ptr,
    float* y_ptr,
    int64_t batch,
    int64_t channels_in,
    int64_t depth_in,
    int64_t height_in,
    int64_t width_in,
    int64_t channels_out,
    int64_t depth_out,
    int64_t height_out,
    int64_t width_out,
    int64_t kernel_d,
    int64_t kernel_h,
    int64_t kernel_w,
    int64_t stride_d,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_d,
    int64_t padding_h,
    int64_t padding_w,
    int64_t groups,
    int64_t channels_in_per_group,
    int64_t channels_out_per_group,
    bool has_bias)
{
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;

    const int64_t outputs_per_batch =
        channels_out * depth_out * height_out * width_out;
    const int64_t output_index =
        static_cast<int64_t>(blockIdx.x) * WARPS_PER_BLOCK + warp;

    if (output_index >= batch * outputs_per_batch) {
        return;
    }

    int64_t linear = output_index;
    const int64_t ow = linear % width_out;
    linear /= width_out;
    const int64_t oh = linear % height_out;
    linear /= height_out;
    const int64_t od = linear % depth_out;
    linear /= depth_out;
    const int64_t oc = linear % channels_out;
    const int64_t n = linear / channels_out;

    auto gX = make_tensor(
        make_gmem_ptr(x_ptr),
        make_shape(batch, channels_in, depth_in, height_in, width_in),
        make_stride(
            channels_in * depth_in * height_in * width_in,
            depth_in * height_in * width_in,
            height_in * width_in,
            width_in,
            Int<1>{}));

    auto gW = make_tensor(
        make_gmem_ptr(w_ptr),
        make_shape(
            channels_in,
            channels_out_per_group,
            kernel_d,
            kernel_h,
            kernel_w),
        make_stride(
            channels_out_per_group * kernel_d * kernel_h * kernel_w,
            kernel_d * kernel_h * kernel_w,
            kernel_h * kernel_w,
            kernel_w,
            Int<1>{}));

    float acc = 0.0f;

    const int64_t group = oc / channels_out_per_group;
    const int64_t oc_in_group = oc - group * channels_out_per_group;
    const int64_t ic_begin = group * channels_in_per_group;
    const int64_t ic_end = ic_begin + channels_in_per_group;

    const int64_t reduction_size =
        channels_in_per_group * kernel_d * kernel_h * kernel_w;

    for (int64_t r = lane; r < reduction_size; r += 32) {
        int64_t t = r;

        const int64_t kw = t % kernel_w;
        t /= kernel_w;
        const int64_t kh = t % kernel_h;
        t /= kernel_h;
        const int64_t kd = t % kernel_d;
        const int64_t ic_offset = t / kernel_d;
        const int64_t ic = ic_begin + ic_offset;

        const int64_t d_num = od + padding_d - kd;
        const int64_t h_num = oh + padding_h - kh;
        const int64_t w_num = ow + padding_w - kw;

        if (d_num >= 0 && h_num >= 0 && w_num >= 0 &&
            d_num % stride_d == 0 &&
            h_num % stride_h == 0 &&
            w_num % stride_w == 0) {
            const int64_t id = d_num / stride_d;
            const int64_t ih = h_num / stride_h;
            const int64_t iw = w_num / stride_w;

            if (id < depth_in && ih < height_in && iw < width_in) {
                acc += gX(n, ic, id, ih, iw) *
                       gW(ic, oc_in_group, kd, kh, kw);
            }
        }
    }

    __shared__ float warp_sums[WARPS_PER_BLOCK];

    float value = acc;
    value += __shfl_down_sync(0xffffffff, value, 16);
    value += __shfl_down_sync(0xffffffff, value, 8);
    value += __shfl_down_sync(0xffffffff, value, 4);
    value += __shfl_down_sync(0xffffffff, value, 2);
    value += __shfl_down_sync(0xffffffff, value, 1);

    if (lane == 0) {
        warp_sums[warp] = value;
        if (has_bias) {
            warp_sums[warp] += bias_ptr[oc];
        }

        const int64_t output_offset =
            (((n * channels_out + oc) * depth_out + od) * height_out + oh) *
            width_out + ow;

        y_ptr[output_offset] = warp_sums[warp];
    }
}


torch::Tensor cute_conv_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_d,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_d,
    int64_t padding_h,
    int64_t padding_w,
    int64_t output_padding_d,
    int64_t output_padding_h,
    int64_t output_padding_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must have shape (N, Cin, D, H, W)");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape (Cin, Cout/groups, Kd, Kh, Kw)");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(stride_d > 0 && stride_h > 0 && stride_w > 0,
                "stride values must be positive");
    TORCH_CHECK(output_padding_d >= 0 && output_padding_h >= 0 &&
                output_padding_w >= 0,
                "output_padding values must be non-negative");
    TORCH_CHECK(output_padding_d < stride_d &&
                output_padding_h < stride_h &&
                output_padding_w < stride_w,
                "output_padding must be smaller than stride");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    const int64_t batch = x_c.size(0);
    const int64_t channels_in = x_c.size(1);
    const int64_t depth_in = x_c.size(2);
    const int64_t height_in = x_c.size(3);
    const int64_t width_in = x_c.size(4);

    TORCH_CHECK(channels_in % groups == 0,
                "input channels must be divisible by groups");
    TORCH_CHECK(w_c.size(0) == channels_in,
                "weight.size(0) must equal input channels");

    const int64_t channels_in_per_group = channels_in / groups;
    const int64_t channels_out_per_group = w_c.size(1);
    const int64_t channels_out = channels_out_per_group * groups;

    const int64_t kernel_d = w_c.size(2);
    const int64_t kernel_h = w_c.size(3);
    const int64_t kernel_w = w_c.size(4);

    const int64_t depth_out =
        (depth_in - 1) * stride_d - 2 * padding_d + kernel_d +
        output_padding_d;
    const int64_t height_out =
        (height_in - 1) * stride_h - 2 * padding_h + kernel_h +
        output_padding_h;
    const int64_t width_out =
        (width_in - 1) * stride_w - 2 * padding_w + kernel_w +
        output_padding_w;

    TORCH_CHECK(depth_out >= 0 && height_out >= 0 && width_out >= 0,
                "invalid output size");

    bool has_bias = bias.defined() && bias.numel() != 0;
    torch::Tensor bias_c;
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
        TORCH_CHECK(bias.dim() == 1 && bias.size(0) == channels_out,
                    "invalid bias shape");
        bias_c = bias.contiguous();
    }

    auto y = torch::empty(
        {batch, channels_out, depth_out, height_out, width_out},
        x_c.options());

    const int64_t total_outputs =
        batch * channels_out * depth_out * height_out * width_out;

    const dim3 block(THREADS_PER_BLOCK);
    const dim3 grid(
        static_cast<unsigned int>(
            (total_outputs + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_conv_transpose3d_kernel<<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        has_bias ? bias_c.data_ptr<float>() : nullptr,
        y.data_ptr<float>(),
        batch,
        channels_in,
        depth_in,
        height_in,
        width_in,
        channels_out,
        depth_out,
        height_out,
        width_out,
        kernel_d,
        kernel_h,
        kernel_w,
        stride_d,
        stride_h,
        stride_w,
        padding_d,
        padding_h,
        padding_w,
        groups,
        channels_in_per_group,
        channels_out_per_group,
        has_bias);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE conv_transpose3d launch failed");

    return y;
}
"""


cute_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv_transpose3d"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1, 1),
        padding: tuple = (0, 0, 0),
        output_padding: tuple = (0, 0, 0),
        groups: int = 1,
        bias: bool = False,
    ) -> None:
        super().__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias = torch.empty(
                0,
                device=x.device,
                dtype=x.dtype,
            )

        return self._ext.cute_conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            bias,
            self.stride[0],
            self.stride[1],
            self.stride[2],
            self.padding[0],
            self.padding[1],
            self.padding[2],
            self.output_padding[0],
            self.output_padding[1],
            self.output_padding[2],
            self.groups,
        )

